-- 2.13.0: Explicit segment results (WINNERS/DRAW/NO_CONTEST) + narration_generated flag.
-- Nullable columns first; V136 tightens them to NOT NULL after the backfills below run.
ALTER TABLE segment ADD COLUMN result VARCHAR(20) DEFAULT 'WINNERS';
ALTER TABLE segment ADD COLUMN narration_generated TINYINT(1) DEFAULT 0;

-- Segments already adjudicated are finished shows: their narration (whatever it holds)
-- is final and must never be regenerated by the new adjudication narration pass.
UPDATE segment SET narration_generated = 1 WHERE adjudication_status = 'ADJUDICATED';
UPDATE segment SET narration_generated = 0 WHERE narration_generated IS NULL;

-- Historical segments that were adjudicated with no winner were counted as draws by
-- every consumer (league stats, season stats, title retention). Stamp them DRAW so
-- history stays consistent and the new result badges render. Non-promo only: promos
-- have no winner concept at all.
UPDATE segment
   SET result = 'DRAW'
 WHERE adjudication_status = 'ADJUDICATED'
   AND segment_type_id <> (SELECT segment_type_id FROM segment_type WHERE name = 'Promo')
   AND NOT EXISTS (
       SELECT 1 FROM segment_participant p
        WHERE p.segment_id = segment.segment_id AND p.is_winner = TRUE);

ALTER TABLE league_roster ADD COLUMN no_contests INT DEFAULT 0;
UPDATE league_roster SET no_contests = 0 WHERE no_contests IS NULL;
